"use client"

import type { ComponentProps } from "react"
import { Menu as MenuPrimitive } from "@base-ui/react/menu"
import { cn } from "cn"

// NOTE: Update these paths if needed
import "../tokens.css"
import "./menu.css"

type ClassName<State> =
  string | ((state: State) => string | undefined) | undefined

function withClass<State>(base: string, className: ClassName<State>) {
  return (state: State) =>
    cn(base, typeof className === "function" ? className(state) : className)
}

function CheckIcon() {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
    >
      <path d="M20 6 9 17l-5-5" />
    </svg>
  )
}

function ChevronRightIcon({ className }: { className?: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      className={className}
    >
      <path d="m9 18 6-6-6-6" />
    </svg>
  )
}

function Menu({ ...props }: MenuPrimitive.Root.Props) {
  return <MenuPrimitive.Root data-slot="menu" {...props} />
}

function MenuPortal({ ...props }: MenuPrimitive.Portal.Props) {
  return <MenuPrimitive.Portal data-slot="menu-portal" {...props} />
}

function MenuTrigger({ ...props }: MenuPrimitive.Trigger.Props) {
  return <MenuPrimitive.Trigger data-slot="menu-trigger" {...props} />
}

function MenuContent({
  align = "start",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 4,
  className,
  ...props
}: MenuPrimitive.Popup.Props &
  Pick<
    MenuPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset"
  >) {
  return (
    <MenuPrimitive.Portal>
      <MenuPrimitive.Positioner
        className="np-menu-positioner"
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
      >
        <MenuPrimitive.Popup
          data-slot="menu-content"
          className={withClass("np-menu-content", className)}
          {...props}
        />
      </MenuPrimitive.Positioner>
    </MenuPrimitive.Portal>
  )
}

function MenuGroup({ className, ...props }: MenuPrimitive.Group.Props) {
  return (
    <MenuPrimitive.Group
      data-slot="menu-group"
      className={withClass("np-menu-group", className)}
      {...props}
    />
  )
}

function MenuLabel({
  className,
  inset,
  ...props
}: MenuPrimitive.GroupLabel.Props & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.GroupLabel
      data-slot="menu-label"
      data-inset={inset ? "" : undefined}
      className={withClass("np-menu-label", className)}
      {...props}
    />
  )
}

function MenuItem({
  className,
  inset,
  variant = "default",
  ...props
}: MenuPrimitive.Item.Props & {
  inset?: boolean
  variant?: "default" | "destructive"
}) {
  return (
    <MenuPrimitive.Item
      data-slot="menu-item"
      data-inset={inset ? "" : undefined}
      data-variant={variant}
      className={withClass(
        cn(
          "np-menu-item",
          variant === "destructive" && "np-menu-item-destructive"
        ),
        className
      )}
      {...props}
    />
  )
}

function MenuSub({ ...props }: MenuPrimitive.SubmenuRoot.Props) {
  return <MenuPrimitive.SubmenuRoot data-slot="menu-sub" {...props} />
}

function MenuSubTrigger({
  className,
  inset,
  children,
  ...props
}: MenuPrimitive.SubmenuTrigger.Props & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.SubmenuTrigger
      data-slot="menu-sub-trigger"
      data-inset={inset ? "" : undefined}
      className={withClass("np-menu-item np-menu-sub-trigger", className)}
      {...props}
    >
      {children}
      <ChevronRightIcon className="np-menu-sub-chevron" />
    </MenuPrimitive.SubmenuTrigger>
  )
}

function MenuSubContent({
  align = "start",
  alignOffset = -3,
  side = "right",
  sideOffset = 0,
  className,
  ...props
}: ComponentProps<typeof MenuContent>) {
  return (
    <MenuContent
      data-slot="menu-sub-content"
      className={withClass("np-menu-sub-content", className)}
      align={align}
      alignOffset={alignOffset}
      side={side}
      sideOffset={sideOffset}
      {...props}
    />
  )
}

function MenuCheckboxItem({
  className,
  children,
  checked,
  inset,
  ...props
}: MenuPrimitive.CheckboxItem.Props & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.CheckboxItem
      data-slot="menu-checkbox-item"
      data-inset={inset ? "" : undefined}
      className={withClass("np-menu-item np-menu-checkbox-item", className)}
      checked={checked}
      {...props}
    >
      <span
        className="np-menu-item-indicator"
        data-slot="menu-checkbox-item-indicator"
      >
        <MenuPrimitive.CheckboxItemIndicator>
          <CheckIcon />
        </MenuPrimitive.CheckboxItemIndicator>
      </span>
      {children}
    </MenuPrimitive.CheckboxItem>
  )
}

function MenuRadioGroup({ ...props }: MenuPrimitive.RadioGroup.Props) {
  return <MenuPrimitive.RadioGroup data-slot="menu-radio-group" {...props} />
}

function MenuRadioItem({
  className,
  children,
  inset,
  ...props
}: MenuPrimitive.RadioItem.Props & {
  inset?: boolean
}) {
  return (
    <MenuPrimitive.RadioItem
      data-slot="menu-radio-item"
      data-inset={inset ? "" : undefined}
      className={withClass("np-menu-item np-menu-radio-item", className)}
      {...props}
    >
      <span
        className="np-menu-item-indicator"
        data-slot="menu-radio-item-indicator"
      >
        <MenuPrimitive.RadioItemIndicator>
          <CheckIcon />
        </MenuPrimitive.RadioItemIndicator>
      </span>
      {children}
    </MenuPrimitive.RadioItem>
  )
}

function MenuSeparator({ className, ...props }: MenuPrimitive.Separator.Props) {
  return (
    <MenuPrimitive.Separator
      data-slot="menu-separator"
      className={withClass("np-menu-separator", className)}
      {...props}
    />
  )
}

/** A keyboard shortcut hint, pushed to the end of the item. */
function MenuShortcut({ className, ...props }: ComponentProps<"span">) {
  return (
    <span
      data-slot="menu-shortcut"
      className={cn("np-menu-shortcut", className)}
      {...props}
    />
  )
}

export {
  Menu,
  MenuPortal,
  MenuTrigger,
  MenuContent,
  MenuGroup,
  MenuLabel,
  MenuItem,
  MenuCheckboxItem,
  MenuRadioGroup,
  MenuRadioItem,
  MenuSeparator,
  MenuShortcut,
  MenuSub,
  MenuSubTrigger,
  MenuSubContent,
}

/* nepui — Menu */


.np-menu,
[data-np-menu],
.np-menu-sub,
[data-np-menu-sub] {
  position: relative;
  display: inline-block;
}

.np-menu-sub,
[data-np-menu-sub] {
  display: block;
}

/* The trigger inside a wrapper becomes the anchor */
:is(.np-menu, [data-np-menu], .np-menu-sub, [data-np-menu-sub])
  > [popovertarget] {
  anchor-name: var(--np-menu-anchor);
}

/* A popover popup: top layer, placed under its trigger, aligned to its start.
   With no anchor support the insets stay `auto`, so it opens next to the trigger. */
:is(.np-menu-content, [data-np-menu-content])[popover] {
  position: fixed;
  inset: auto;
  margin: 0;
  border: 0;
  position-anchor: var(--np-menu-anchor);
  top: calc(anchor(bottom) + var(--np-menu-offset, 0.25rem));
  left: anchor(left);
  min-width: max(var(--np-menu-min-width, 8rem), anchor-size(width));
  position-try-fallbacks: flip-block, flip-inline;
  opacity: 0;
  transform: scale(0.95);
  transition:
    opacity 100ms ease,
    transform 100ms ease,
    display 100ms allow-discrete,
    overlay 100ms allow-discrete;
}

:is(.np-menu-content, [data-np-menu-content])[popover]:popover-open {
  opacity: 1;
  transform: none;
}

@starting-style {
  :is(.np-menu-content, [data-np-menu-content])[popover]:popover-open {
    opacity: 0;
    transform: scale(0.95);
  }
}

/* A submenu opens beside its trigger */
:is(.np-menu-sub-content, [data-np-menu-sub-content])[popover] {
  top: anchor(top);
  left: calc(anchor(right) + var(--np-menu-offset, 0.25rem));
  margin-top: -0.25rem;
}

/* ==========================================================================
   Popup surface
   ========================================================================== */

.np-menu-positioner,
[data-np-menu-positioner] {
  isolation: isolate;
  z-index: 50;
  outline: none;
}

.np-menu-content,
[data-np-menu-content] {
  z-index: 50;
  box-sizing: border-box;
  min-width: max(var(--np-menu-min-width, 8rem), var(--anchor-width, 0px));
  max-height: var(--available-height, 24rem);
  overflow-x: hidden;
  overflow-y: auto;
  padding: 0.25rem;

  border-radius: var(--np-menu-radius, var(--np-radius-md));
  background: var(--np-menu-bg, var(--np-popover, var(--np-background)));
  color: var(
    --np-menu-color,
    var(--np-popover-foreground, var(--np-foreground))
  );
  box-shadow:
    0 0 0 1px color-mix(in oklch, var(--np-foreground) 10%, transparent),
    0 4px 6px -1px rgb(0 0 0 / 0.1),
    0 2px 4px -2px rgb(0 0 0 / 0.1);

  font-size: 0.875rem;
  outline: none;
  transform-origin: var(--transform-origin, top left);
}

.np-menu-sub-content,
[data-np-menu-sub-content] {
  --np-menu-min-width: 6rem;
  min-width: max(var(--np-menu-min-width), 6rem);
  box-shadow:
    0 0 0 1px color-mix(in oklch, var(--np-foreground) 10%, transparent),
    0 10px 15px -3px rgb(0 0 0 / 0.1),
    0 4px 6px -4px rgb(0 0 0 / 0.1);
}

/* Base UI open / close transition (scale, fade, slide from the trigger) */
:is(.np-menu-content, [data-np-menu-content]):not([popover]) {
  transition:
    opacity 100ms ease,
    transform 100ms ease,
    translate 100ms ease;
}

:is(.np-menu-content, [data-np-menu-content]):not([popover]):is(
    [data-starting-style],
    [data-ending-style]
  ) {
  opacity: 0;
  transform: scale(0.95);
}

:is(.np-menu-content, [data-np-menu-content])[data-side="bottom"]:is(
    [data-starting-style],
    [data-ending-style]
  ) {
  translate: 0 -0.5rem;
}

:is(.np-menu-content, [data-np-menu-content])[data-side="top"]:is(
    [data-starting-style],
    [data-ending-style]
  ) {
  translate: 0 0.5rem;
}

:is(.np-menu-content, [data-np-menu-content]):is(
    [data-side="right"],
    [data-side="inline-end"]
  ):is([data-starting-style], [data-ending-style]) {
  translate: -0.5rem 0;
}

:is(.np-menu-content, [data-np-menu-content]):is(
    [data-side="left"],
    [data-side="inline-start"]
  ):is([data-starting-style], [data-ending-style]) {
  translate: 0.5rem 0;
}

/* ==========================================================================
   Group, label, separator
   ========================================================================== */

.np-menu-group,
[data-np-menu-group] {
  display: block;
}

.np-menu-label,
[data-np-menu-label] {
  padding: 0.25rem 0.375rem;
  color: var(--np-muted-foreground);
  font-size: 0.75rem;
  font-weight: 500;
}

.np-menu-separator,
[data-np-menu-separator] {
  height: 1px;
  margin: 0.25rem -0.25rem;
  border: 0;
  background: var(--np-border);
}

/* ==========================================================================
   Item
   ========================================================================== */

.np-menu-item,
[data-np-menu-item] {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.375rem;
  box-sizing: border-box;
  width: 100%;
  margin: 0;
  padding: 0.25rem 0.375rem;

  border: 0;
  border-radius: var(--np-menu-item-radius, 0.375rem);
  background: transparent;
  color: inherit;

  font: inherit;
  font-size: 0.875rem;
  line-height: 1.25rem;
  text-align: start;
  text-decoration: none;

  cursor: default;
  outline: none;
  -webkit-user-select: none;
  user-select: none;
}

:is(.np-menu-item, [data-np-menu-item]) svg {
  flex-shrink: 0;
  pointer-events: none;
}

:is(.np-menu-item, [data-np-menu-item]) svg:not([class*="size-"]) {
  width: 1rem;
  height: 1rem;
}

/* Highlighted: keyboard, hover, or an open submenu */
:is(.np-menu-item, [data-np-menu-item]):is(
  :focus,
  [data-highlighted],
  [data-popup-open],
  [data-open],
  :hover
) {
  background: var(--np-menu-hover-bg, var(--np-accent, var(--np-muted)));
  color: var(
    --np-menu-hover-color,
    var(--np-accent-foreground, var(--np-foreground))
  );
}

/* Disabled */
:is(.np-menu-item, [data-np-menu-item]):is(
  :disabled,
  [data-disabled],
  [aria-disabled="true"]
) {
  pointer-events: none;
  opacity: 0.5;
}

/* Inset: room for the check mark column of a neighbouring checkbox item */
:is(
  .np-menu-item,
  .np-menu-label,
  [data-np-menu-item],
  [data-np-menu-label]
)[data-inset],
.np-menu-inset {
  padding-inline-start: 1.75rem;
}

/* Destructive */
.np-menu-item-destructive,
:is(.np-menu-item, [data-np-menu-item])[data-variant="destructive"] {
  color: var(--np-destructive);
}

:is(
  .np-menu-item-destructive,
  :is(.np-menu-item, [data-np-menu-item])[data-variant="destructive"]
):is(:focus, [data-highlighted], [data-popup-open], [data-open], :hover) {
  background: var(
    --np-menu-destructive-bg,
    color-mix(in oklch, var(--np-destructive) 10%, transparent)
  );
  color: var(--np-destructive);
}

/* Checkbox and radio items: the check mark sits at the end */
:is(.np-menu-checkbox-item, .np-menu-radio-item) {
  padding-inline-end: 2rem;
}

.np-menu-item-indicator,
[data-np-menu-item-indicator] {
  position: absolute;
  inset-inline-end: 0.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

/* Plain HTML renders the indicator always; hide it unless checked */
:is(.np-menu-checkbox-item, .np-menu-radio-item):is(
    [aria-checked="false"],
    [data-unchecked]
  )
  > :is(.np-menu-item-indicator, [data-np-menu-item-indicator]) {
  display: none;
}

/* Submenu trigger */
.np-menu-sub-chevron,
[data-np-menu-sub-chevron] {
  margin-inline-start: auto;
}

:dir(rtl) :is(.np-menu-sub-chevron, [data-np-menu-sub-chevron]) {
  transform: scaleX(-1);
}

/* ==========================================================================
   Shortcut
   ========================================================================== */

.np-menu-shortcut,
[data-np-menu-shortcut] {
  margin-inline-start: auto;
  color: var(--np-muted-foreground);
  font-size: 0.75rem;
  letter-spacing: 0.1em;
}

:is(.np-menu-item, [data-np-menu-item]):is(
    :focus,
    [data-highlighted],
    [data-popup-open],
    [data-open],
    :hover
  )
  :is(.np-menu-shortcut, [data-np-menu-shortcut]) {
  color: var(
    --np-menu-hover-color,
    var(--np-accent-foreground, var(--np-foreground))
  );
}

/* ==========================================================================
   Reduced motion
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  :is(.np-menu-content, [data-np-menu-content]) {
    transition: none;
  }
}

/* ==========================================================================
   Dark
   1. Explicit: `.dark` or `data-theme="dark"` on any ancestor.
   2. System: prefers-color-scheme, unless `.light` / `data-theme="light"`.
   Variables are set on the popup; items inherit them (they are read with
   fallbacks, never redeclared).
   ========================================================================== */

:is(.dark, [data-theme="dark"]) :is(.np-menu-content, [data-np-menu-content]) {
  --np-menu-destructive-bg: color-mix(
    in oklch,
    var(--np-destructive) 20%,
    transparent
  );
}

@media (prefers-color-scheme: dark) {
  :root:not(.light, [data-theme="light"])
    :is(.np-menu-content, [data-np-menu-content]) {
    --np-menu-destructive-bg: color-mix(
      in oklch,
      var(--np-destructive) 20%,
      transparent
    );
  }
}
